// AI DISCLAIMER: All of the text in this file was generated by AI.
/* pagemap2: G016 research tool, read only. pagemap plus page types: labels every page of an LMDB environment with the
 * table it belongs to, and labels a table's overflow (large-value) pages separately, as "<table>:ov".
 * stdout adds, per table: branch, leaf and overflow pages, the number of large values, and the overflow share.
 *
 * Walks every named sub-database (its branch, leaf and overflow pages, dupsort sub-trees included), the main DB's own
 * pages ("@main"), the freelist DB's own pages ("@freedb") and the pages it lists as free ("@free"). Pages below
 * next_pgno that no tree reaches are "@none" (for example pages freed by a transaction readers still pin).
 * Overflow pages are labelled from the leaf node that points at them; they are never read.
 *
 * Opened as monerod opens it, with MDB_RDONLY | MDB_NORDAHEAD | MDB_NOLOCK: it writes nothing (no lock file), so it
 * must not run while a writer has the environment open.
 *
 * usage: pagemap <lmdb dir | data file> <out runs file>
 *   out: one line per run of pages with the same label, "<first page> <last page> <label>", in page order.
 *   stdout: per label, pages and MB; and the totals.
 * Built against the vendored mdb.c (its page-format macros), as idxwarm is.
 */
#define _GNU_SOURCE
#include "mdb.c"

#include <sys/stat.h>

#define MAXLAB 250
static const char *g_names[MAXLAB];
static int g_nlab;
static unsigned char *g_lab;  /* per page: 0 = none, else label index + 1 */
static char *g_map;
static unsigned g_psize;
static pgno_t g_next;
static size_t g_dups;
/* per label index: branch, leaf (LEAF2 included), overflow pages, large values */
static size_t g_br[MAXLAB], g_lf[MAXLAB], g_ov[MAXLAB], g_big[MAXLAB];
static int label(const char *name);
static int ovlabel(int lab)
{
	char nm[600];
	snprintf(nm, sizeof nm, "%s:ov", g_names[lab]);
	return label(nm);
}

static int label(const char *name)
{
	int i;
	for (i = 0; i < g_nlab; i++) if (!strcmp(g_names[i], name)) return i;
	if (g_nlab == MAXLAB) { fprintf(stderr, "too many labels\n"); exit(2); }
	g_names[g_nlab] = strdup(name);
	return g_nlab++;
}

static void mark(pgno_t pg, int lab)
{
	if (pg >= g_next) { fprintf(stderr, "page %llu beyond next_pgno %llu\n", (unsigned long long)pg, (unsigned long long)g_next); exit(3); }
	if (g_lab[pg] && g_lab[pg] != lab + 1) g_dups++;
	g_lab[pg] = (unsigned char)(lab + 1);
}

typedef struct { pgno_t *v; size_t n, cap; } stack;
static void push(stack *s, pgno_t p)
{
	if (s->n == s->cap) {
		s->cap = s->cap ? 2 * s->cap : 4096;
		s->v = realloc(s->v, s->cap * sizeof(pgno_t));
		if (!s->v) { perror("realloc"); exit(2); }
	}
	s->v[s->n++] = p;
}

/* Walk one tree from its root. Children of branch pages, dupsort sub-tree roots and overflow runs get the same label.
 * Named sub-databases (F_SUBDATA without F_DUPDATA, only in the main DB) are not followed: each is walked by name. */
static size_t walk(pgno_t root, int lab)
{
	stack s = {0};
	size_t n = 0;
	push(&s, root);
	while (s.n) {
		pgno_t pg = s.v[--s.n];
		MDB_page *mp;
		unsigned i, nk;
		mark(pg, lab); n++;
		mp = (MDB_page *)(g_map + (size_t)pg * g_psize);
		if (IS_LEAF2(mp)) { g_lf[lab]++; continue; }
		nk = NUMKEYS(mp);
		if (IS_BRANCH(mp)) {
			g_br[lab]++;
			for (i = 0; i < nk; i++) push(&s, NODEPGNO(NODEPTR(mp, i)));
			continue;
		}
		if (!IS_LEAF(mp)) { fprintf(stderr, "page %llu: flags 0x%x\n", (unsigned long long)pg, mp->mp_flags); exit(3); }
		g_lf[lab]++;
		for (i = 0; i < nk; i++) {
			MDB_node *node = NODEPTR(mp, i);
			if (node->mn_flags & F_BIGDATA) {
				pgno_t ov, k, cnt;
				memcpy(&ov, NODEDATA(node), sizeof ov);
				cnt = OVPAGES(NODEDSZ(node), g_psize);
				{ int ol = ovlabel(lab); for (k = 0; k < cnt; k++) { mark(ov + k, ol); n++; } }
				g_ov[lab] += cnt; g_big[lab]++;
			} else if ((node->mn_flags & F_SUBDATA) && (node->mn_flags & F_DUPDATA)) {
				MDB_db db;
				memcpy(&db, NODEDATA(node), sizeof db);
				if (db.md_root != P_INVALID) push(&s, db.md_root);
			}
		}
	}
	free(s.v);
	return n;
}

int main(int argc, char **argv)
{
	MDB_env *env;
	MDB_txn *txn;
	MDB_cursor *cur;
	MDB_val k, v;
	MDB_stat st;
	struct stat fst;
	FILE *out;
	int rc, i;
	size_t *count;
	pgno_t p, start;

	if (argc != 3) { fprintf(stderr, "usage: %s <lmdb dir> <out runs file>\n", argv[0]); return 1; }
	if ((rc = mdb_env_create(&env)) || (rc = mdb_env_set_maxdbs(env, 64)) ||
	    (rc = mdb_env_open(env, argv[1], MDB_RDONLY | MDB_NORDAHEAD | MDB_NOLOCK | (stat(argv[1], &fst) == 0 && S_ISREG(fst.st_mode) ? MDB_NOSUBDIR : 0), 0644))) {
		fprintf(stderr, "env: %s\n", mdb_strerror(rc)); return 2;
	}
	mdb_env_stat(env, &st);
	g_map = env->me_map; g_psize = st.ms_psize;
	if ((rc = mdb_txn_begin(env, NULL, MDB_RDONLY, &txn))) { fprintf(stderr, "txn: %s\n", mdb_strerror(rc)); return 2; }
	g_next = txn->mt_next_pgno;
	g_lab = calloc(g_next, 1);
	if (!g_lab) { perror("calloc"); return 2; }
	/* pages 0 and 1 are the meta pages */
	mark(0, label("@meta")); mark(1, label("@meta"));

	/* the named sub-databases: the keys of the main DB */
	if ((rc = mdb_cursor_open(txn, MAIN_DBI, &cur))) { fprintf(stderr, "cursor: %s\n", mdb_strerror(rc)); return 2; }
	while ((rc = mdb_cursor_get(cur, &k, &v, MDB_NEXT)) == 0) {
		char name[512];
		MDB_dbi dbi;
		MDB_db *db;
		if (k.mv_size >= sizeof name) { fprintf(stderr, "long key in the main DB\n"); return 2; }
		memcpy(name, k.mv_data, k.mv_size); name[k.mv_size] = 0;
		if ((rc = mdb_dbi_open(txn, name, 0, &dbi))) { fprintf(stderr, "%s: %s\n", name, mdb_strerror(rc)); return 2; }
		db = &txn->mt_dbs[dbi];
		if (db->md_root != P_INVALID) {
			size_t n = walk(db->md_root, label(name));
			size_t want = db->md_branch_pages + db->md_leaf_pages + db->md_overflow_pages;
			/* reported, not enforced: whether md_*_pages of a dupsort DB count its sub-trees is checked by this output */
			printf("db %s walked %zu stat %zu%s\n", name, n, want, n == want ? "" : " (differ)");
		}
	}
	if (rc != MDB_NOTFOUND) { fprintf(stderr, "main DB cursor: %s\n", mdb_strerror(rc)); return 2; }
	mdb_cursor_close(cur);

	/* the main DB's own pages (its leaves hold the sub-database records, which walk() does not follow) */
	if (txn->mt_dbs[MAIN_DBI].md_root != P_INVALID) walk(txn->mt_dbs[MAIN_DBI].md_root, label("@main"));
	/* the freelist DB's own pages, then the pages it lists */
	if (txn->mt_dbs[FREE_DBI].md_root != P_INVALID) {
		int lf = label("@free");
		walk(txn->mt_dbs[FREE_DBI].md_root, label("@freedb"));
		if ((rc = mdb_cursor_open(txn, FREE_DBI, &cur))) { fprintf(stderr, "free cursor: %s\n", mdb_strerror(rc)); return 2; }
		while ((rc = mdb_cursor_get(cur, &k, &v, MDB_NEXT)) == 0) {
			MDB_ID *idl = (MDB_ID *)v.mv_data;
			MDB_ID j;
			for (j = 1; j <= idl[0]; j++) mark(idl[j], lf);
		}
		if (rc != MDB_NOTFOUND) { fprintf(stderr, "free DB cursor: %s\n", mdb_strerror(rc)); return 2; }
		mdb_cursor_close(cur);
	}

	out = fopen(argv[2], "w");
	if (!out) { perror(argv[2]); return 2; }
	count = calloc(g_nlab + 1, sizeof *count);
	for (p = 0, start = 0; p <= g_next; p++) {
		if (p == g_next || (p > start && g_lab[p] != g_lab[start])) {
			fprintf(out, "%llu %llu %s\n", (unsigned long long)start, (unsigned long long)(p - 1),
				g_lab[start] ? g_names[g_lab[start] - 1] : "@none");
			start = p;
		}
		if (p < g_next) count[g_lab[p]]++;
	}
	fclose(out);
	printf("psize %u next_pgno %llu pages labelled twice %zu\n", g_psize, (unsigned long long)g_next, g_dups);
	for (i = 0; i <= g_nlab; i++)
		if (count[i]) printf("label %s pages %zu MB %.1f\n", i ? g_names[i - 1] : "@none", count[i], count[i] * (double)g_psize / 1e6);
	for (i = 0; i < g_nlab; i++) {
		size_t t = g_br[i] + g_lf[i] + g_ov[i];
		if (t && !strchr(g_names[i], ':'))
			printf("type %s branch %zu leaf %zu overflow %zu bigvalues %zu overflow_share %.4f overflow_MB %.1f\n", g_names[i],
				g_br[i], g_lf[i], g_ov[i], g_big[i], (double)g_ov[i] / t, g_ov[i] * (double)g_psize / 1e6);
	}
	mdb_txn_abort(txn);
	mdb_env_close(env);
	return g_dups ? 4 : 0;
}
